<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { StoneSnapshot } from '../../shared/protocol'
import { GAME_DEFINITIONS } from '../../shared/gameCatalog'
import { GO_SIZES, stoneCoordinate, stoneSideName, type StoneBoard as StoneBoardState, type StoneMove, type StoneSide } from '../../shared/stones'
import type { GameController } from '../useGame'
import { useBoardPlayback } from '../useBoardPlayback'
import StoneBoard from '../components/StoneBoard.vue'
import BrandMark from '../components/BrandMark.vue'
import GameTools from '../components/GameTools.vue'
import AppIcon from '../components/AppIcon.vue'
import DialogShell from '../components/DialogShell.vue'
import HostTools from '../components/HostTools.vue'
import SeatRequestPanel from '../components/SeatRequestPanel.vue'

const props = defineProps<{ game: GameController }>()
const s = computed<StoneSnapshot | null>(() => { const v = props.game.state.value; return v?.game === 'go' || v?.game === 'gomoku' ? v : null })
const emit = defineEmits<{ animating: [value: boolean] }>()
const { board, playback, animating } = useBoardPlayback(s, props.game.connected, {
  position: snap => ({ roundId: snap.stones.roundId, layout: `${snap.game}:${snap.stones.size}`, board: snap.stones.board, moves: snap.stones.moves }),
  empty: [] as StoneBoardState,
  canAnimate: (before, move) => move.point !== null && before[move.point] === null,
})
watch(animating, value => emit('animating', value), { immediate: true, flush: 'sync' })
const name = computed(() => s.value ? GAME_DEFINITIONS[s.value.game].name : '')
const shared = computed(() => s.value?.roomMode === 'tablet'), side = computed(() => s.value?.selfSeat as StoneSide | null)
const acting = computed<StoneSide>(() => (shared.value ? s.value?.turn ?? 0 : side.value ?? 0) as StoneSide)
const me = computed(() => s.value?.seats.find(p => p.id === side.value))
const paused = computed(() => !props.game.connected.value || !shared.value && !!s.value?.seats.some(p => p.name !== null && !p.connected))
const localBusy = ref(false), locked = computed(() => localBusy.value || props.game.busy.value || !props.game.connected.value || animating.value)
const canPlay = computed(() => s.value?.phase === 'playing' && s.value.stones.stage === 'play' && !locked.value && !paused.value && (shared.value ? s.value.isHost : side.value !== null && s.value.turn === side.value))
const canScore = computed(() => s.value?.phase === 'playing' && s.value.stones.stage === 'scoring' && !locked.value && !paused.value && (shared.value ? s.value.isHost : side.value !== null))
const canStart = computed(() => shared.value || !!s.value?.seats.every(p => p.name !== null && p.connected && p.ready))
const selected = ref<number | null>(null), inviteOpen = ref(false), historyOpen = ref(false), historyPage = ref(0), resignOpen = ref(false), resignSide = ref<StoneSide>(0), passOpen = ref(false), requestsOpen = ref(false), copied = ref('')
const moves = computed(() => s.value?.stones.moves.slice(historyPage.value*6,(historyPage.value+1)*6) ?? [])
const lastMove = computed<StoneMove | null>(() => s.value?.stones.moves.at(-1) ?? null)
const lastSummary = computed(() => {
  const move = lastMove.value, snapshot = s.value
  if (!move || !snapshot) return ''
  const size = snapshot.stones.size, lead = `${animating.value ? '落子中' : '上一手'} · 第 ${move.ply} 手 · ${stoneSideName(move.side)}`
  if (move.point === null) return `${lead} · 停一手`
  const point = stoneCoordinate(move.point, size)
  if (snapshot.game !== 'go') return `${lead} · ${point}`
  const captured = move.captured.map(p => stoneCoordinate(p, size))
  return `${lead} · ${point} · ${captured.length ? `提 ${captured.length} 子（${captured.slice(0, 5).join('、')}${captured.length > 5 ? '…' : ''}）` : '提 0 子'}`
})
watch(() => s.value?.version, () => { selected.value = null })
const title = computed(() => !s.value ? '' : s.value.phase === 'lobby' ? shared.value ? '两人同屏，直接开局。' : '邀一位朋友，一起落子。' : animating.value ? '落子中，稍候。' : s.value.phase === 'finished' ? s.value.stones.draw ? '和棋，下局再见。' : `${stoneSideName(s.value.stones.winner!)}获胜。` : paused.value ? '等朋友回来，再继续。' : s.value.stones.stage === 'scoring' ? '双方确认死子与结果。' : canPlay.value ? shared.value ? `轮到${stoneSideName(acting.value)}。` : '轮到你了。' : `等待${stoneSideName(s.value.turn!)}落子。`)
const instruction = computed(() => !s.value ? '' : s.value.phase === 'lobby' ? shared.value ? '两人轮流操作同一块平板，黑方先行。' : '双方入座并准备后，由房主开始。黑方先行。' : s.value.phase === 'finished' ? s.value.stones.reason : s.value.stones.stage === 'scoring' ? '点击棋子，标记或取消整块死子；双方确认后才结算。有争议可继续下棋。' : selected.value !== null ? `预选 ${stoneCoordinate(selected.value,s.value.stones.size)}，点“确认落子”才会提交。` : s.value.game === 'go' ? '点空交叉点预选，再确认落子。提子由系统完成。' : '点空交叉点预选，再确认落子。横、竖、斜先连五子或以上获胜。')
async function run(action: () => Promise<void> | void): Promise<void> { if (localBusy.value) return; localBusy.value = true; try { await action() } catch (e) { props.game.error.value = e instanceof Error ? e.message : '操作失败' } finally { localBusy.value = false } }
function select(point: number): void {
  if (!s.value) return
  if (canScore.value && s.value.stones.board[point] !== null) void run(() => props.game.stoneScore('mark',point,shared.value ? 0 : undefined))
  else if (canPlay.value && s.value.stones.board[point] === null) selected.value = selected.value === point ? null : point
}
function place(): void { const point = selected.value; if (point !== null && canPlay.value) { selected.value = null; void run(() => props.game.stoneMove(point)) } }
async function copy(seat: number): Promise<void> { try { await navigator.clipboard.writeText(props.game.inviteUrl(seat)); copied.value = `已复制${stoneSideName(seat)}链接` } catch { copied.value = '可以长按链接复制' } }
</script>
<template>
  <section v-if="s" class="stone-screen" :data-game="s.game" :data-phase="s.phase" :data-stage="s.stones.stage" :data-shared="shared">
    <header class="stone-header"><div class="stone-brand"><BrandMark /><strong>{{ name }}</strong><small>{{ s.code }}</small></div><div><GameTools :game="game" /><button class="tool-button" :disabled="localBusy || game.busy.value" @click="run(game.leaveRoom)"><AppIcon name="home" /><span>大厅</span></button></div></header>
    <div class="stone-layout">
      <div class="stone-intro"><h1>{{ title }}</h1><p role="status">{{ instruction }}</p></div>
      <div class="stone-board-column"><div class="stone-board-meta"><span>{{ shared ? '双人同屏' : side === null ? '公开棋盘' : `你执${stoneSideName(side)}` }} · {{ s.stones.size }} 路</span><span>{{ s.game === 'go' ? '数子法 · 黑贴 7.5 点' : '无禁手 · 长连也获胜' }}</span></div><p v-if="lastSummary" class="stone-last-move" role="status">{{ lastSummary }}</p><div class="stone-board-frame"><StoneBoard :board="board" :size="s.stones.size" :selected="selected" :preview-side="acting" :last="lastMove?.point ?? null" :live="playback" :dead="s.stones.dead" :winning-line="s.stones.winningLine" :ownership="s.stones.score?.ownership" :disabled="!canPlay && !canScore" @select="select" /></div></div>
      <aside class="stone-panel">
        <label v-if="s.game === 'go' && s.phase === 'lobby'" class="stone-size">棋盘<select :value="s.stones.size" :disabled="locked || !s.isHost" @change="run(() => game.stoneSetup(Number(($event.target as HTMLSelectElement).value)))"><option v-for="size in GO_SIZES" :key="size" :value="size">{{ size }} 路{{ size === 9 ? ' · 入门推荐' : size === 19 ? ' · 标准棋盘' : ' · 进阶练习' }}</option></select><small>更换棋盘后需重新准备</small></label>
        <div class="stone-roster"><article v-for="seat in s.seats" :key="seat.id" :class="{ active: s.turn === seat.id && s.phase === 'playing' }"><i :class="seat.id === 0 ? 'black' : 'white'"></i><div><strong>{{ seat.name ?? `等待${stoneSideName(seat.id)}` }}<small v-if="seat.id === side">我</small><small v-if="s.hostSeatId === seat.id">房主</small></strong><span>{{ shared ? stoneSideName(seat.id) : !seat.name ? '空位' : !seat.connected ? '等待重连' : s.phase === 'lobby' ? seat.ready ? '已准备' : '未准备' : stoneSideName(seat.id) }}<template v-if="s.game === 'go'"> · 提 {{ s.stones.captured[seat.id] }} 子</template></span></div></article></div>
        <div v-if="s.phase === 'lobby'" class="stone-actions"><button v-if="!shared && side !== null" class="button" :class="me?.ready ? 'secondary' : 'primary'" :disabled="locked" @click="run(game.ready)">{{ me?.ready ? '取消准备' : '我准备好了' }}</button><button v-if="s.isHost" class="button primary" :disabled="locked || !canStart" @click="run(game.start)">开始对弈</button></div>
        <template v-else-if="s.phase === 'playing' && s.stones.stage === 'play'"><div class="stone-actions"><button class="button primary stone-place" :disabled="!canPlay || selected === null" @click="place">确认落子{{ selected === null ? '' : ` · ${stoneCoordinate(selected,s.stones.size)}` }}</button><button v-if="s.game === 'go'" class="button secondary" :disabled="!canPlay" @click="passOpen = true">停一手</button><button class="button secondary" :disabled="locked || side === null && !shared" @click="resignSide = acting; resignOpen = true">认输</button></div><p v-if="s.game === 'go' && s.stones.passes" class="stone-note">对方已停一手。你也停一手后进入死子确认，尚未直接判胜。</p></template>
        <template v-else-if="s.phase === 'playing' && s.stones.stage === 'scoring'"><div v-if="s.stones.score" class="stone-score"><strong>黑 {{ s.stones.score.total[0] }} 点 / 白 {{ s.stones.score.total[1] }} 点</strong><span>黑：{{ s.stones.score.stones[0] }} 子 + {{ s.stones.score.territory[0] }} 空；白：{{ s.stones.score.stones[1] }} 子 + {{ s.stones.score.territory[1] }} 空 + 7.5 贴点</span></div><div class="stone-actions"><template v-if="shared"><button v-for="color in ([0,1] as const)" :key="color" class="button primary" :disabled="!canScore || s.stones.confirmed[color]" @click="run(() => game.stoneScore('confirm',undefined,color))">{{ stoneSideName(color) }}{{ s.stones.confirmed[color] ? '已确认' : '确认结果' }}</button></template><button v-else class="button primary" :disabled="!canScore || side === null || s.stones.confirmed[side]" @click="run(() => game.stoneScore('confirm'))">{{ side !== null && s.stones.confirmed[side] ? '已确认，等待对方' : '确认死子与结果' }}</button><button class="button secondary" :disabled="!canScore" @click="run(() => game.stoneScore('resume',undefined,shared ? 0 : undefined))">继续下棋</button></div></template>
        <div v-else-if="s.phase === 'finished'" class="stone-actions"><button v-if="s.isHost" class="button primary" :disabled="locked" @click="run(game.again)">再来一局</button><span v-else class="stone-note">等待房主再开一局</span></div>
        <div class="stone-utilities"><button v-if="!shared" class="tool-button" @click="inviteOpen = true"><AppIcon name="users" />邀请朋友</button><button class="tool-button" :disabled="!s.stones.moves.length" @click="historyPage = Math.floor((s!.stones.moves.length-1)/6); historyOpen = true"><AppIcon name="history" />棋谱</button><HostTools v-if="s.isHost" :phase="s.phase" :room-mode="s.roomMode" :seats="s.seats" :self-seat="side" :busy="locked" @remove-offline="run(game.removeOfflineSeats)" @transfer="seat => run(() => game.transferHost(seat))" @dissolve="run(game.dissolveRoom)" /></div>
        <button v-if="s.isHost && s.seatRequests.length" class="tool-button" @click="requestsOpen = true">处理入座申请（{{ s.seatRequests.length }}）</button>
      </aside>
    </div>
    <DialogShell v-if="passOpen" title="确认停一手？" @close="passOpen = false"><p class="stone-dialog-copy">表示本回合不落子。如果对方上一手也停了，将进入死子确认；双方确认后才结算。</p><button class="button primary" :disabled="locked" @click="passOpen = false; run(game.stonePass)">确认停一手</button></DialogShell>
    <DialogShell v-if="resignOpen" :title="`确认${stoneSideName(resignSide)}认输？`" @close="resignOpen = false"><p class="stone-dialog-copy">认输后对方获胜，本局结束。</p><div v-if="shared" class="stone-actions"><button v-for="color in ([0,1] as const)" :key="color" class="button secondary" :aria-pressed="resignSide === color" @click="resignSide = color">{{ stoneSideName(color) }}</button></div><button class="button primary" :disabled="locked" @click="resignOpen = false; run(() => game.stoneResign(shared ? resignSide : undefined))">确认认输</button></DialogShell>
    <DialogShell v-if="inviteOpen" :title="`邀请朋友下${name}`" @close="inviteOpen = false"><p class="stone-dialog-copy">朋友连接同一局域网，打开空位一方的链接入座。</p><div v-for="seat in s.seats" :key="seat.id" class="stone-invite"><button class="button secondary" @click="copy(seat.id)">复制{{ stoneSideName(seat.id) }}链接</button><a :href="game.inviteUrl(seat.id)">{{ game.inviteUrl(seat.id) }}</a></div><p role="status">{{ copied }}</p></DialogShell>
    <DialogShell v-if="historyOpen" title="本局棋谱" @close="historyOpen = false"><ol class="stone-history"><li v-for="move in moves" :key="move.ply"><span>{{ move.ply }}. {{ stoneSideName(move.side) }}</span><strong>{{ move.notation }}</strong></li></ol><nav class="stone-actions"><button class="button secondary" :disabled="historyPage === 0" @click="historyPage--">上一页</button><span>{{ historyPage+1 }} / {{ Math.max(1,Math.ceil(s.stones.moves.length/6)) }}</span><button class="button secondary" :disabled="(historyPage+1)*6 >= s.stones.moves.length" @click="historyPage++">下一页</button></nav></DialogShell>
    <DialogShell v-if="requestsOpen && s.isHost && s.seatRequests.length" title="入座申请" @close="requestsOpen = false"><SeatRequestPanel :requests="s.seatRequests" :busy="locked" @decide="(id,approve) => run(() => game.decideSeatRequest(id,approve))" /></DialogShell>
  </section>
</template>
<style>
.stone-screen { height: 100dvh; padding: max(8px,env(safe-area-inset-top)) max(16px,env(safe-area-inset-right)) max(10px,env(safe-area-inset-bottom)) max(16px,env(safe-area-inset-left)); display: flex; flex-direction: column; gap: 10px; overflow: hidden; background: #f2efe2; color: #294f3c; }
.stone-header { display: flex; align-items: center; justify-content: space-between; min-height: 42px; gap: 10px; flex: none; padding-bottom: 6px; border-bottom: 1px solid #d1d8bf; }.stone-header > div,.stone-brand { display: flex; align-items: center; gap: 10px; }.stone-brand strong { font: 23px 'Songti SC',serif; white-space: nowrap; }.stone-brand .brand-mark { width: 28px; height: 28px; }.stone-brand small { font-size: 10px; color: #899575; }
.stone-layout { display: flex; flex-direction: column; flex: 1; min-height: 0; gap: 10px; width: 100%; max-width: 850px; margin: 0 auto; }.stone-intro { flex: none; }.stone-intro h1 { font: clamp(22px,3vw,30px) 'Songti SC',serif; margin: 0 0 4px; }.stone-intro p { font-size: 11px; line-height: 1.6; color: #7d8b6d; margin: 0; }
.stone-board-column { flex: 1; min-height: 0; display: flex; flex-direction: column; }.stone-board-meta { display: flex; justify-content: space-between; gap: 8px; color: #81906e; font-size: 10px; padding: 0 4px 5px; flex: none; }.stone-board-frame { flex: 1; min-height: 0; }.stone-last-move { flex: none; margin: 0 4px 5px; padding: 3px 8px; border-left: 2px solid #b09355; border-radius: 0 5px 5px 0; background: #ebe4cf; color: #5c6c4d; font-size: 10px; line-height: 1.5; overflow-wrap: anywhere; }
.stone-panel { display: flex; flex: none; flex-direction: column; gap: 9px; }.stone-size { display: flex; align-items: center; gap: 9px; font-size: 12px; color: #778966; }.stone-size select { padding: 7px; min-height: 36px; border: 1px solid #c9d2b7; border-radius: 7px; background: #faf8ed; color: #31543e; }.stone-size small { font-size: 10px; }
.stone-roster { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }.stone-roster article { display: flex; gap: 9px; align-items: center; padding: 9px 12px; border: 1px solid #cdd5ba; border-radius: 11px; background: #f9f7ec; min-width: 0; }.stone-roster article.active { border-color: #b29a58; background: #f8efd5; }.stone-roster i { width: 26px; height: 26px; border-radius: 50%; flex: none; border: 1px solid #adae96; }.stone-roster .black { background: radial-gradient(at 30% 25%,#686e60,#1f2b20); }.stone-roster .white { background: radial-gradient(at 30% 25%,#fffef5,#dbdac7); }.stone-roster article > div { min-width: 0; }.stone-roster strong { display: block; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }.stone-roster strong small { font-size: 9px; font-weight: normal; margin-left: 4px; color: #81906e; }.stone-roster span { display: block; font-size: 10px; color: #859574; margin-top: 3px; }
.stone-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 7px; }.stone-actions .button { flex: 1; min-height: 38px; padding: 7px 8px; font-size: 11px; white-space: nowrap; }.stone-actions .stone-place { flex: 2; }.stone-actions > span { font-size: 10px; color: #7d8c6b; }.stone-note { font-size: 10px; color: #8a805c; line-height: 1.6; }.stone-score { padding: 8px 10px; border-radius: 8px; border: 1px solid #cdd5bb; background: #faf8ed; }.stone-score strong { display: block; font-size: 13px; font-weight: 500; }.stone-score span { display: block; font-size: 10px; color: #7d896a; margin-top: 4px; }
.stone-utilities { display: flex; align-items: center; gap: 6px; padding-top: 4px; border-top: 1px solid #d0d8bd; }.stone-utilities .host-tools { margin-left: auto; }.stone-utilities .host-tools-menu { top: auto; bottom: calc(100% + 7px); }.stone-dialog-copy { font-size: 13px; line-height: 1.8; color: #7a886a; margin: 0 0 16px; }.stone-invite { display: flex; align-items: center; gap: 10px; margin: 12px 0; }.stone-invite .button { flex: none; padding: 8px; font-size: 11px; }.stone-invite a { font-size: 11px; overflow-wrap: anywhere; min-width: 0; }.stone-history { list-style: none; margin: 0 0 14px; padding: 0; }.stone-history li { display: flex; justify-content: space-between; gap: 10px; font-size: 12px; padding: 9px 0; border-bottom: 1px solid #d5dbc6; }.stone-history strong { font-weight: 500; }.stone-history span { color: #899476; }
@media (max-width:430px) { .stone-screen { padding-inline: 12px; gap: 8px; }.stone-header { gap: 5px; }.stone-header > div { gap: 6px; }.stone-header .tool-button { padding-inline: 7px; }.stone-brand { gap: 6px; }.stone-brand .brand-mark { display: none; }.stone-size { flex-wrap: wrap; gap: 6px; }.stone-size small { margin-left: auto; }.stone-intro h1 { font-size: 23px; }.stone-roster article { padding: 7px 9px; } }
@media (max-height:650px) and (orientation:portrait) { .stone-screen { gap: 5px; padding-top: 5px; padding-bottom: 5px; }.stone-header { min-height: 32px; padding-bottom: 3px; }.stone-header .tool-button { min-height: 30px; font-size: 10px; padding: 4px 6px; }.stone-brand strong { font-size: 19px; }.stone-layout { gap: 5px; }.stone-intro h1 { font-size: 20px; }.stone-intro p { font-size: 10px; }.stone-panel { gap: 5px; }.stone-size select { min-height: 30px; font-size: 12px; padding: 4px; }.stone-size small { font-size: 9px; }.stone-roster article { padding: 5px 7px; }.stone-roster i { width: 20px; height: 20px; }.stone-roster strong { font-size: 11px; }.stone-roster span { font-size: 9px; margin-top: 1px; }.stone-actions .button { min-height: 32px; padding: 5px; font-size: 10px; }.stone-utilities .tool-button { min-height: 28px; padding: 4px 6px; font-size: 10px; }.stone-score { padding: 5px 7px; }.stone-score strong { font-size: 11px; }.stone-score span { font-size: 9px; }.stone-last-move { font-size: 9px; padding: 2px 6px; margin-bottom: 3px; } }
</style>
